const input = $input.all()[0].json;
const profile = input.founder_profile;

if (!profile || !profile.search_keywords) {
  return [{ json: { status: 'error', error: 'No founder_profile or search_keywords provided', investors: [] } }];
}

const investorTypeQueries = ['venture capital', 'angel investor', 'syndicate', 'VC partner', 'managing partner VC'];
const industryQueries = profile.industry_tags || [];
const stageQueries = profile.funding_stage ? [profile.funding_stage.replace('_', ' ')] : [];
const geoQueries = profile.geo_preferences || [];

const searchQueries = [];
for (const investorType of investorTypeQueries) {
  for (const industry of industryQueries.slice(0, 3)) {
    const query = `${investorType} ${industry}`;
    searchQueries.push(query);
    for (const geo of geoQueries.slice(0, 2)) {
      searchQueries.push(`${query} ${geo}`);
    }
  }
}

const connectionDegrees = ['F', 'S', 'O'];

return [{
  json: {
    founder_profile: profile,
    search_queries: [...new Set(searchQueries)].slice(0, 20),
    connection_degrees: connectionDegrees,
    linkedin_method: profile.linkedin_credentials?.method || 'automation',
    linkedin_token: profile.linkedin_credentials?.token || ''
  }
}];

const response = $input.all()[0].json;

const investors = [];
const elements = response?.elements || response?.data?.elements || [];

for (const el of elements) {
  const title = (el.title?.text || el.headline || '').toLowerCase();
  let investorType = 'Unknown';
  if (title.includes('venture') || title.includes('vc') || title.includes('partner')) investorType = 'VC';
  else if (title.includes('angel')) investorType = 'Angel';
  else if (title.includes('syndicate')) investorType = 'Syndicate';
  else continue;

  investors.push({
    name: el.title?.text || el.name || 'Unknown',
    title: el.headline || el.title?.text || '',
    company: el.subline?.text || el.company || '',
    connection_degree: el.connectionDegree || el.distance || '3rd',
    profile_url: el.navigationUrl || el.publicProfileUrl || '',
    investor_type: investorType
  });
}

return [{ json: { status: 'success', investors, count: investors.length } }];

const response = $input.all()[0].json;

let investors = [];
if (response?.investors && Array.isArray(response.investors)) {
  investors = response.investors;
} else if (response?.result?.investors && Array.isArray(response.result.investors)) {
  investors = response.result.investors;
} else if (response?.data?.investors && Array.isArray(response.data.investors)) {
  investors = response.data.investors;
}

const normalized = investors.map(inv => ({
  name: inv.name || 'Unknown',
  title: inv.title || '',
  company: inv.company || '',
  connection_degree: inv.connection_degree || '3rd',
  profile_url: inv.profile_url || '',
  investor_type: inv.investor_type || 'Unknown'
}));

return [{ json: { status: 'success', investors: normalized, count: normalized.length } }];

const items = $input.all();
let allInvestors = [];

for (const item of items) {
  if (item.json.investors && Array.isArray(item.json.investors)) {
    allInvestors = allInvestors.concat(item.json.investors);
  }
}

const seen = new Map();
for (const inv of allInvestors) {
  const key = (inv.profile_url || `${inv.name}_${inv.company}`).toLowerCase();
  if (!seen.has(key)) {
    seen.set(key, inv);
  }
}

const deduplicated = Array.from(seen.values());

return [{ json: { status: 'success', investors: deduplicated, count: deduplicated.length } }];
